package agent

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent/types"
)

// TextCommandRunner matches exec.CommandContext and allows tests to inject a runner.
type TextCommandRunner func(ctx context.Context, name string, args ...string) *exec.Cmd

// RunIsolatedTextGeneratorCLI executes a text-generation CLI in an isolated temp
// directory with all GIT_* environment variables removed. This avoids recursive
// hook triggers and repo side effects while preserving provider-specific flags.
func RunIsolatedTextGeneratorCLI(ctx context.Context, runner TextCommandRunner, binary, displayName string, args []string, stdin string) (string, error) {
	if runner == nil {
		runner = exec.CommandContext
	}

	cmd := runner(ctx, binary, args...)
	cmd.Dir = os.TempDir()
	cmd.Env = StripGitEnv(os.Environ())
	if stdin != "" {
		cmd.Stdin = strings.NewReader(stdin)
	}

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	if err := cmd.Run(); err != nil {
		if errors.Is(ctx.Err(), context.DeadlineExceeded) {
			return "", context.DeadlineExceeded
		}
		if errors.Is(ctx.Err(), context.Canceled) {
			return "", context.Canceled
		}
		var execErr *exec.Error
		if errors.As(err, &execErr) {
			return "", fmt.Errorf("%s CLI not found: %w", displayName, err)
		}
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			detail := strings.TrimSpace(stderr.String())
			if detail == "" {
				detail = strings.TrimSpace(stdout.String())
			}
			if detail == "" {
				detail = err.Error()
			}
			return "", fmt.Errorf("%s CLI failed (exit %d): %s: %w", displayName, exitErr.ExitCode(), detail, err)
		}
		return "", fmt.Errorf("failed to run %s CLI: %w", displayName, err)
	}

	result := strings.TrimSpace(stdout.String())
	if result == "" {
		return "", fmt.Errorf("%s CLI returned empty output", displayName)
	}
	return result, nil
}

// summaryProviderBinaries maps agent names to the CLI binary that
// RunIsolatedTextGeneratorCLI will exec. Used by IsSummaryCLIAvailable to
// check PATH instead of repo-level DetectPresence, because a repo can use
// one agent for development while a different agent generates summaries.
var summaryProviderBinaries = map[types.AgentName]string{
	AgentNameClaudeCode: "claude",
	AgentNameCodex:      "codex",
	AgentNameCopilotCLI: "copilot",
	AgentNameCursor:     "agent",
	AgentNameGemini:     "gemini",
}

// IsSummaryCLIAvailable reports whether the CLI binary for a summary-capable
// agent is on PATH. This is distinct from DetectPresence, which checks
// repo-level agent configuration — a repo configured with Claude Code for
// development can still use Codex or Gemini for summary generation as long
// as the binary is installed.
func IsSummaryCLIAvailable(name types.AgentName) bool {
	binary, ok := summaryProviderBinaries[name]
	if !ok {
		return false
	}
	_, err := exec.LookPath(binary)
	return err == nil
}

func StripGitEnv(env []string) []string {
	filtered := make([]string, 0, len(env))
	for _, e := range env {
		if !strings.HasPrefix(e, "GIT_") {
			filtered = append(filtered, e)
		}
	}
	return filtered
}

// Package review — see env.go for package-level rationale.
//
// dump.go provides DumpSink, a Sink implementation that writes a
// per-agent narrative dump to an io.Writer after the run completes.
// AgentEvent is a no-op; events are read from RunSummary.AgentRuns[].Buffer
// in RunFinished.
//
// Output format: each agent's block is composed as markdown (`# claude-code
// review`, with failure context in blockquotes/bold) and rendered through
// mdrender for terminal writers. Non-TTY writers receive raw markdown so
// pipelines can grep / pipe / save without ANSI escape codes.
package review

import (
	"errors"
	"fmt"
	"io"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/mdrender"
	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// DumpSink writes per-agent narrative blocks to W after the run completes.
type DumpSink struct {
	W io.Writer
	// RenderWriter is the writer whose terminal capabilities should be used for
	// markdown rendering. It defaults to W. TTY review runs use this when W is a
	// post-run buffer that will later flush to the real terminal.
	RenderWriter io.Writer
}

// Compile-time interface check.
var _ reviewtypes.Sink = DumpSink{}

// AgentEvent is intentionally a no-op. DumpSink renders post-run from
// the AgentRun.Buffer slices in RunFinished.
func (DumpSink) AgentEvent(_ string, _ reviewtypes.Event) {}

// RunFinished writes a narrative block per agent, then a counts line.
func (s DumpSink) RunFinished(summary reviewtypes.RunSummary) {
	for _, run := range summary.AgentRuns {
		s.dumpAgent(run)
	}
	s.dumpCounts(summary)
}

// dumpAgent composes one agent's section as markdown and writes it through
// mdrender. The counts line at the end of the run is intentionally NOT
// rendered through markdown — it's a terse status summary that benefits
// from staying on a single uncolored line for grep-ability.
//
// Markdown structure per agent:
//
//	# <name> review
//	(optional status line for cancelled / failed)
//	(optional blockquote for RunError events on failure)
//	(narrative — agent's AssistantText events joined)
func (s DumpSink) dumpAgent(run reviewtypes.AgentRun) {
	var b strings.Builder
	fmt.Fprintf(&b, "# %s review\n\n", run.Name)

	switch run.Status {
	case reviewtypes.AgentStatusCancelled:
		b.WriteString("_cancelled_\n")
	case reviewtypes.AgentStatusFailed:
		// Surface the wait error if any (process exit failure), then any
		// agent-level RunError events the parser emitted (typically a torn
		// stdout stream — caught at the orchestrator level by classifyStatus
		// even when the process itself exited 0).
		writeFailureHeader(&b, run.Err)
		for _, ev := range run.Buffer {
			re, ok := ev.(reviewtypes.RunError)
			if !ok || re.Err == nil {
				continue
			}
			if sameFailureError(re.Err, run.Err) {
				continue
			}
			fmt.Fprintf(&b, "> agent error: `%v`\n\n", re.Err)
		}
		// Render any narrative text the agent produced before the failure
		// surfaced — useful when the parser tore mid-response so reviewers
		// can see partial output instead of a bare "(failed)" line.
		if narrative := joinAssistantText(run.Buffer); narrative != "" {
			b.WriteString(narrative)
			b.WriteString("\n")
		}
	case reviewtypes.AgentStatusSucceeded, reviewtypes.AgentStatusUnknown:
		if narrative := joinAssistantText(run.Buffer); narrative != "" {
			b.WriteString(narrative)
			b.WriteString("\n")
		}
	}

	// RenderForWriter is TTY-aware: returns raw markdown for non-TTY writers,
	// glamour-styled output otherwise. Errors are best-effort — fall back to
	// raw markdown so the user always gets the content.
	rendered, err := mdrender.RenderForWriter(s.renderWriter(), b.String())
	if err != nil {
		rendered = b.String()
	}
	fmt.Fprint(s.W, rendered)
}

func (s DumpSink) renderWriter() io.Writer {
	if s.RenderWriter != nil {
		return s.RenderWriter
	}
	return s.W
}

func writeFailureHeader(b *strings.Builder, runErr error) {
	if runErr == nil {
		b.WriteString("**Failed**\n\n")
		return
	}
	var pe *reviewtypes.ProcessError
	if errors.As(runErr, &pe) && pe.Stderr != "" {
		fmt.Fprintf(b, "**Failed:** `%s` exited (`%v`). Stderr:\n\n", pe.AgentName, pe.Err)
		fence := codeFenceFor(pe.Stderr)
		fmt.Fprintf(b, "%s\n%s\n%s\n\n", fence, pe.Stderr, fence)
		return
	}
	fmt.Fprintf(b, "**Failed:** `%v`\n\n", runErr)
}

// codeFenceFor returns a backtick fence at least 3 long and at least one
// longer than the longest backtick run in s — per CommonMark §4.5, the
// closing fence must match or exceed the opening fence length, so this
// prevents stderr content with embedded ``` lines from terminating the
// fence early and rendering trailing content raw.
func codeFenceFor(s string) string {
	longest, current := 0, 0
	for _, r := range s {
		if r == '`' {
			current++
			if current > longest {
				longest = current
			}
			continue
		}
		current = 0
	}
	n := longest + 1
	if n < 3 {
		n = 3
	}
	return strings.Repeat("`", n)
}

func sameFailureError(a, b error) bool {
	if a == nil || b == nil {
		return false
	}
	return errors.Is(a, b) || errors.Is(b, a)
}

// joinAssistantText extracts AssistantText events from a buffer and joins
// them with newlines, trimming the result to keep dump output tight.
func joinAssistantText(buf []reviewtypes.Event) string {
	var b strings.Builder
	for _, ev := range buf {
		if at, ok := ev.(reviewtypes.AssistantText); ok {
			b.WriteString(at.Text)
			b.WriteString("\n")
		}
	}
	return strings.TrimSpace(b.String())
}

func (s DumpSink) dumpCounts(summary reviewtypes.RunSummary) {
	succ, fail, canc := 0, 0, 0
	for _, r := range summary.AgentRuns {
		switch r.Status {
		case reviewtypes.AgentStatusSucceeded:
			succ++
		case reviewtypes.AgentStatusFailed:
			fail++
		case reviewtypes.AgentStatusCancelled:
			canc++
		case reviewtypes.AgentStatusUnknown:
			// Unknown status: not counted in any bucket.
		}
	}
	fmt.Fprintf(s.W, "%d agent(s) done — %d succeeded, %d failed, %d cancelled\n",
		len(summary.AgentRuns), succ, fail, canc)
}

// Render produces a glamour-styled string from markdown using the entire
// CLI palette. width is the word-wrap target; darkBackground selects the
// dark or light palette variant.
//
// Errors only on glamour renderer construction or render failure — both
// of which indicate a malformed StyleConfig (programmer error) rather
// than a runtime condition. Renderer panics are recovered and returned as
// errors so callers can fall back to raw markdown instead of crashing.
func Render(markdown string, width int, darkBackground bool) (rendered string, err error) {
	defer func() {
		if r := recover(); r != nil {
			rendered = ""
			err = fmt.Errorf("render markdown panic: %v", r)
		}
	}()

	renderer, err := glamour.NewTermRenderer(
		glamour.WithStyles(stylesForBackground(darkBackground)),
		glamour.WithWordWrap(width),
		glamour.WithPreservedNewLines(),
	)
	if err != nil {
		return "", fmt.Errorf("initialize markdown renderer: %w", err)
	}
	rendered, err = renderer.Render(markdown)
	if err != nil {
		return "", fmt.Errorf("render markdown: %w", err)
	}
	return rendered, nil
}

// RenderForWriter renders markdown when w is a terminal writer, and returns
// the input unchanged otherwise. NO_COLOR=1 also disables rendering so
// pipelines that grep through redirected output work without unwrapping
// ANSI escape sequences.
//
// Width is auto-detected from w (capped at 80); background palette is
// detected via termenv.HasDarkBackground.
func RenderForWriter(w io.Writer, markdown string) (string, error) {
	if !shouldRender(w) {
		return markdown, nil
	}
	return Render(markdown, terminalWidth(w), termenv.HasDarkBackground())
}

// shouldRender returns true when styled output is appropriate for w
// (terminal writer, NO_COLOR unset, no legacy console) — see
// interactive.ShouldStyle.
func shouldRender(w io.Writer) bool {
	return interactive.ShouldStyle(w)
}

// terminalWidth returns the writer's terminal width capped at 80.
// Falls back to stdout/stderr probing, then DefaultTerminalWidth.
func terminalWidth(w io.Writer) int {
	if f, ok := w.(*os.File); ok {
		if width, _, err := term.GetSize(int(f.Fd())); err == nil && width > 0 { //nolint:gosec // G115: uintptr->int is safe for fd
			return min(width, DefaultTerminalWidth)
		}
	}
	for _, f := range []*os.File{os.Stdout, os.Stderr} {
		if f == nil {
			continue
		}
		if width, _, err := term.GetSize(int(f.Fd())); err == nil && width > 0 { //nolint:gosec // G115: uintptr->int is safe for fd
			return min(width, DefaultTerminalWidth)
		}
	}
	return DefaultTerminalWidth
}

